mapper.select:
SELECT id
FROM training_task
WHERE status = 'IN_PROGRESS'
  AND updated_at < #{cutoff}
ORDER BY updated_at
LIMIT #{limit}

SELECT id
FROM training_task_execution
WHERE status = 'RUNNING'
  AND started_at < #{cutoff}
ORDER BY started_at
LIMIT #{limit}

SELECT task_id
FROM training_knowledge_index_task
WHERE status = 'RUNNING'
  AND started_at < #{cutoff}
ORDER BY started_at
LIMIT #{limit}
